def verify(witness):
    B=witness['basis_check_range']
    probes=witness['probe_points']
    width=B.bit_length()
    even_mask=int('01'*width,2)   # bits at positions 0,2,4,...
    odd_mask=int('10'*width,2)    # bits at positions 1,3,5,...
    A0=set(); A1=set()
    for n in range(B):
        if (n & even_mask)==n:
            A0.add(n)
        if (n & even_mask)==0:
            A1.add(n)
    A=A0|A1
    # (a) basis of order 2 on the full verified range, via exact digit split
    for n in range(B):
        a0=n & even_mask
        a1=n-a0
        if a0 not in A0 or a1 not in A1 or a0+a1!=n:
            raise ValueError('basis property fails at n=%d' % n)
    # (b) representation counts at probe points: each >=2 and strictly increasing
    prev=-1
    Al=sorted(A)
    for m in probes:
        r=0
        for a in Al:
            if a>m:
                break
            if (m-a) in A:
                r+=1
        if r<=prev or r<2:
            raise ValueError('representation count not increasing at m=%d' % m)
        prev=r

_witness={'basis_check_range':1048576,
          'probe_points':[4,16,64,256,1024,4096,16384,65536,262144]}
verify(_witness)
